mapper.select:
SELECT orc.* FROM t_iam_oauth2_registered_client orc


        AND orc.client_id LIKE CONCAT('%', #{inputDto.clientId}, '%')


        AND orc.client_name LIKE CONCAT('%', #{inputDto.clientName}, '%')


        AND orc.status = #{inputDto.status}


        AND orc.update_time > #{inputDto.updateStartTime}


        AND orc.update_time  <  #{inputDto.updateEndTime}


ORDER BY orc.create_time DESC
